import bisect
import numpy as np


def clean(rows):
    speeds = []
    seen_hours = set()
    for row in rows:
        hour, sep, speed = row.partition(',')
        if not sep:
            continue
        hour = hour.strip()
        try:
            value = float(speed.strip())
        except ValueError:
            continue
        if hour not in seen_hours:
            seen_hours.add(hour)
            speeds.append(value)
    return speeds


def summary(speeds):
    return {
        'count': len(speeds),
        'mean': round(float(np.mean(speeds)), 2),
        'median': float(np.median(speeds)),
        'std': round(float(np.std(speeds, ddof=0)), 2),
    }


def top(speeds, n):
    return [float(x) for x in sorted(speeds, reverse=True)[:n]]


def count_over(speeds, limit):
    ordered = sorted(speeds)
    return len(ordered) - bisect.bisect_right(ordered, limit)
